        <div class="col-12 col-md-4"><label class="form-label" for="inp_trip_trip_type">Trip Type *</label><select id="inp_trip_trip_type" class="form-select form-select-sm">@foreach(['Local','Outstation','Airport Transfer','Corporate','Other'] as $type)<option @selected(($trip?->trip_type ?? 'Local') === $type)>{{ $type }}</option>@endforeach</select></div>
