        <div class="col-6 col-md-3"><label class="form-label" for="inp_trip_additional_charges">Extra Charges (₹)</label><input id="inp_trip_additional_charges" type="number" min="0" step=".01" value="{{ $trip?->additional_charges ?? 0 }}" oninput="updateTripPreview()" class="form-control form-control-sm"></div>
